// Test-only scoped outage accounting; production retry policy is unchanged.
fn fastest_cut_retries(ms:u64)->u64{
 // reconnect_delay: half-to-full jitter of min(500*2^failure,10000)ms.
 let mut elapsed=0;let mut count=0;
 for gap in [250u64,500,1000,2000,4000]{elapsed+=gap;if elapsed>ms{return count}count+=1;}
 count+(ms-elapsed)/5000
}
fn outage_view(v:&Value)->Value{json!({"fixture_current":v["fixture_current"],"g3":{"live_transport":v["g3"]["live_transport"],"movement":v["g3"]["movement"],"movement_failure":v["g3"]["movement_failure"]}})}
fn outage_delta(before:&Value,after:&Value,path:&str)->Result<u64,String>{after.pointer(path).and_then(Value::as_u64).zip(before.pointer(path).and_then(Value::as_u64)).and_then(|(a,b)|a.checked_sub(b)).ok_or_else(||format!("Missing/regressed outage counter {path}"))}
fn outage_scope(before:&[Value;2],after:&[Value;2])->Result<(),String>{
 if let Some(event)=transport_change(before,after,[true,false]){return Err(format!("Scoped outage transport guard: {event}"))}
 for i in 0..2{let current=&after[i]["fixture_current"];if current["playing"]!=true||current["native_controls"]!=true||current["identity"]!=before[i]["fixture_current"]["identity"]||current["native"]["holds"]!=before[i]["fixture_current"]["native"]["holds"]{return Err(format!("Scoped outage changed current owner/permission/Controls side{i}"))}}
 for path in ["/g3/movement/live_admission_renewal_retries","/g3/movement/live_renewal_requests","/g3/movement/live_renewals_consumed"]{if outage_delta(&before[0],&after[0],path)?!=0{return Err("Physical WSS cut cannot excuse admission renewal/refusal".into())}}
 let transport=&after[0]["g3"]["live_transport"];
 if !transport["last_receive_failure"].is_null(){return Err("Physical WSS cut cannot excuse a protocol receive diagnostic".into())}
 if let Some(error)=transport["last_error"].as_str(){if !["Live peer closed","Live connection unavailable","Live connect deadline","Live upgrade deadline","Live upgrade refused","Live control send deadline","Live send deadline","Live receive deadline"].contains(&error){return Err(format!("Not a scoped transport closure/deadline: {error}"))}}
 Ok(())
}
fn outage_finish(before:&[Value;2],after:&[Value;2],cut_ms:u64,service_before:&Value,service_after:&Value)->Result<Value,String>{
 outage_scope(before,after)?;auth_phase(&service_before["liveAuth"],&service_after["liveAuth"])?;capacity_phase(&service_before["liveCapacity"],&service_after["liveCapacity"])?;
 let attempts=outage_delta(&before[0],&after[0],"/g3/live_transport/attempts")?;let failures=outage_delta(&before[0],&after[0],"/g3/live_transport/failures")?;let connections=outage_delta(&before[0],&after[0],"/g3/movement/live_connections")?;let retries=fastest_cut_retries(cut_ms);
 if connections!=1||attempts==0||attempts>retries+1||failures>retries+1||failures>attempts+1{return Err(format!("Outage attempts/failures exceed actual cut/backoff bound or successful connection differs: attempts={attempts},failures={failures},connections={connections},cut_ms={cut_ms},max_failed_retries={retries}"))}
 if outage_delta(&before[0],&after[0],"/g3/movement_failure/count")?!=failures{return Err("Outage contains an additional non-transport movement failure".into())}
 Ok(json!({"cut_ms":cut_ms,"maximum_failed_retries_at_fastest_production_backoff":retries,"maximum_attempts_including_one_successful_reconnection":retries+1,"attempt_delta":attempts,"transport_failure_delta":failures,"successful_connection_delta":connections,"same_current_owner_permission_controls":true,"healthy_peer_unchanged":true,"service_auth_capacity_protocol_failure_excused":false}))
}
fn outage_service(service:&mut Service)->Value{let auth=service.command(json!({"op":"liveAuthStatus"}));let capacity=service.command(json!({"op":"liveCapacityStatus"}));json!({"liveAuth":auth["liveAuth"],"liveCapacity":capacity["liveCapacity"]})}
fn outage_cut_sample(before:&[Value;2],previous:&[Value;2],current:&[Value;2],elapsed_ms:u64)->Result<(),String>{outage_scope(previous,current)?;outage_scope(before,current)?;if outage_delta(&before[0],&current[0],"/g3/movement/live_connections")?!=0{return Err("Successful WSS connection during an enabled cut".into())}if outage_delta(&before[0],&current[0],"/g3/live_transport/attempts")?>fastest_cut_retries(elapsed_ms){return Err("Retry attempts exceed fastest production backoff during actual cut".into())}Ok(())}
pub(super) struct ScopedWssOutage{root:std::path::PathBuf,before:[Value;2],previous:[Value;2],service_before:Value,samples:Vec<Value>}
impl ScopedWssOutage{
 pub(super) fn start(service:&mut Service,root:&std::path::Path,before:&[Value;2])->Self{let before=[outage_view(&before[0]),outage_view(&before[1])];Self{root:root.to_path_buf(),previous:before.clone(),before,service_before:outage_service(service),samples:vec![]}}
 pub(super) fn observe(&mut self,elapsed_ms:u64,current:&[Value;2]){
  let current=[outage_view(&current[0]),outage_view(&current[1])];let result=if self.samples.len()>=256{Err("Outage observer sample bound exceeded".to_string())}else{outage_cut_sample(&self.before,&self.previous,&current,elapsed_ms)};
  if self.samples.len()<256{self.samples.push(json!({"elapsed_ms":elapsed_ms,"current":current}));}if let Err(reason)=result{std::fs::write(self.root.join("wss-outage-first-loss.json"),serde_json::to_vec_pretty(&json!({"reason":reason,"before":self.before,"samples":self.samples})).unwrap()).unwrap();panic!("{reason}")};self.previous=current;
 }
 pub(super) fn finish(self,service:&mut Service,cut_ms:u64,recovery_ms:u64,after:&[Value;2]){
  let after=[outage_view(&after[0]),outage_view(&after[1])];let service_after=outage_service(service);let result=outage_finish(&self.before,&after,cut_ms,&self.service_before,&service_after);let report=json!({"before":self.before,"after":after,"actual_cut_window_ms":cut_ms,"observed_recovery_ms":recovery_ms,"recovery_wait_not_inflated":true,"service_before":self.service_before,"service_after":service_after,"samples":self.samples,"check":result.as_ref().ok(),"failure":result.as_ref().err()});std::fs::write(self.root.join("wss-outage-check.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();result.unwrap();
 }
}
#[test]fn lc1_network_scoped_outage_replays_actual07_and_rejects_unrelated_failures(){
 let root=repo().join("spikes/noita-entry/.build/lc1-network-client-20261020-07/same-process-wss-322bd226-27f9-43d4-b4f6-a45f4c25d18e");let rows:Vec<Value>=std::fs::read_to_string(root.join("ghost-checks.jsonl")).unwrap().lines().map(|line|serde_json::from_str(line).unwrap()).collect();
 let row=|label:&str|rows.iter().find(|r|r["label"]==label).unwrap();let pair=|r:&Value|[json!({"fixture_current":r["a"],"g3":r["aCounters"]}),json!({"fixture_current":r["b"],"g3":r["bCounters"]})];let before=pair(row("same-process replacement fresh scoped bidirectional poses and native rendering"));let after=pair(row("WSS-only reconnect fresh poses and rendering with permission retained"));let diagnostics:Value=serde_json::from_slice(&std::fs::read(root.join("network-failure-service-diagnostics.json")).unwrap()).unwrap();let service=json!({"liveAuth":diagnostics["diagnostics"]["liveAuthStatus"]["liveAuth"],"liveCapacity":diagnostics["diagnostics"]["liveCapacityStatus"]["liveCapacity"]});
 assert_eq!(before[0]["g3"]["live_transport"]["attempts"],3);assert_eq!(after[0]["g3"]["live_transport"]["attempts"],12);assert_eq!(after[0]["g3"]["movement"]["live_connections"],4);let proof=outage_finish(&before,&after,35000,&service,&service).unwrap();assert_eq!(proof["attempt_delta"],9);assert_eq!(proof["transport_failure_delta"],9);assert_eq!(fastest_cut_retries(35000),10);
 for fault in 0..10{let mut bad=after.clone();match fault{0=>bad[1]["g3"]["live_transport"]["attempts"]=json!(2),1=>bad[0]["g3"]["live_transport"]["last_error"]=json!("FORBIDDEN"),2=>bad[0]["g3"]["live_transport"]["last_error"]=json!("CAPACITY"),3=>bad[0]["g3"]["live_transport"]["last_receive_failure"]=json!({"retire_code":"STALE_EPOCH"}),4=>bad[0]["g3"]["movement"]["live_renewal_requests"]=json!(1),5=>bad[0]["g3"]["live_transport"]["attempts"]=json!(100),6=>bad[0]["fixture_current"]["native_controls"]=json!(false),7=>bad[0]["g3"]["movement"]["live_connections"]=json!(5),8=>bad[1]["fixture_current"]["identity"]["context"]=json!("retired"),_=>bad[0]["g3"]["live_transport"]["last_error"]=json!("INVALID_MESSAGE")};assert!(outage_finish(&before,&bad,35000,&service,&service).is_err(),"Outage excused unrelated failure{fault}");}
 let mut capacity=service.clone();capacity["liveCapacity"]["counts"]=json!({"traffic-pose-burst":1});assert!(outage_finish(&before,&after,35000,&service,&capacity).is_err());let mut auth=service.clone();let mut event=auth["liveAuth"]["events"][0].clone();event["outcome"]=json!("FORBIDDEN");auth["liveAuth"]["firstFailure"]=event;assert!(outage_finish(&before,&after,35000,&service,&auth).is_err());
 let source=include_str!("g3_live.rs");assert!(source.contains("let ceiling=(500u64.saturating_mul(1u64<<failures.min(5))).min(10000);"));assert!(source.contains("ceiling/2+random%(ceiling/2+1)"));assert_eq!((fastest_cut_retries(249),fastest_cut_retries(250),fastest_cut_retries(749),fastest_cut_retries(750)),(0,1,1,2));let mut early=before.clone();early[0]["g3"]["live_transport"]["attempts"]=json!(4);assert!(outage_cut_sample(&before,&before,&early,249).is_err());outage_cut_sample(&before,&before,&early,250).unwrap();let out=repo().join("spikes/noita-entry/.build/lc1-network-client-20261020-11");std::fs::create_dir_all(&out).unwrap();std::fs::write(out.join("actual07-outage-replay.json"),serde_json::to_vec_pretty(&json!({"boundary":"immutable actual07 before/after snapshots and cumulative failure-unwind service diagnostics; no shared run","cut_ms_used":35000,"cut_bound":"unchanged driver minimum duration, conservative; not an invented measured timestamp","before":before,"after":after,"check":proof,"negative_cases":13})).unwrap()).unwrap();
}
